using GH_Net.Core.Enums;
using GH_Net.Licensing;
using GH_Net.Repository.Abstractions;
using GH_Net.Service.Abstractions;

namespace GH_Net.Service.Implements;

public sealed class JobRuntimeCoordinator : IJobRuntimeCoordinator, IDisposable
{
    private readonly IJobService _jobs; private readonly IPackingRuntimeService _runtime; private readonly IScannerConfigService _scannerConfig; private readonly IZebraPrinterConfigService _printerConfig; private readonly IScannerDevice _scanner; private readonly IZebraPrinterDevice _printer; private readonly ILicenseManager _license; private readonly IZplTemplateRenderer _renderer; private readonly SemaphoreSlim _gate=new(1,1); private int? _activeJobId; private JobStatus _status=JobStatus.NewlyCreated; private bool _disposed;
    public JobRuntimeCoordinator(IJobService jobs,IPackingRuntimeService runtime,IScannerConfigService scannerConfig,IZebraPrinterConfigService printerConfig,IScannerDevice scanner,IZebraPrinterDevice printer,ILicenseManager license,IZplTemplateRenderer renderer){_jobs=jobs;_runtime=runtime;_scannerConfig=scannerConfig;_printerConfig=printerConfig;_scanner=scanner;_printer=printer;_license=license;_renderer=renderer;_runtime.RuntimeFailed+=OnFailed;_runtime.SnapshotChanged+=OnSnapshot;}
    public int? ActiveJobId=>_activeJobId; public JobStatus CurrentStatus=>_status; public event Action<JobStatus>? StatusChanged; public event Action<Exception>? RuntimeFailed;
    public async Task StartAsync(int jobId,CancellationToken ct=default){ObjectDisposedException.ThrowIf(_disposed,this);await _gate.WaitAsync(ct);try{if(_activeJobId.HasValue&&_activeJobId!=jobId)throw new InvalidOperationException("Another Job is active.");var job=await _jobs.GetByIdWithDetailsAsync(jobId,ct)??throw new InvalidOperationException("Job not found.");if(!_license.Current.IsValid||!_license.HasFeature(LicenseFeature.Scanner)||!_license.HasFeature(LicenseFeature.Printer))throw new InvalidOperationException("A valid Scanner and Printer license is required.");var sc=await _scannerConfig.GetAsync(ct)??throw new InvalidOperationException("Scanner settings are missing.");var pc=await _printerConfig.GetAsync(ct)??throw new InvalidOperationException("Zebra printer settings are missing.");if(!sc.Enabled||!_scanner.IsConnected||!string.Equals(_scanner.CurrentPortName,sc.PortName,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Connect the configured COM scanner before starting.");if(!_printer.IsConnected||!string.Equals(_printer.CurrentIp,pc.Ip,StringComparison.OrdinalIgnoreCase)||_printer.CurrentPort!=pc.Port)throw new InvalidOperationException("Connect the configured Zebra printer before starting.");_renderer.Validate(pc.CartonZplTemplate??"");_renderer.Validate(pc.PalletZplTemplate??"");_activeJobId=jobId;await _runtime.StartAsync(jobId,ct);SetStatus(JobStatus.Running);}finally{_gate.Release();}}
    public async Task StopAsync(CancellationToken ct=default){await _gate.WaitAsync(ct);try{if(!_activeJobId.HasValue)return;try{await _runtime.StopAsync(ct);}finally{if(!_runtime.IsRunning)SetStatus(_runtime.Current?.WorkflowState==PackingWorkflowState.Completed?JobStatus.Completed:JobStatus.Paused);}}finally{_gate.Release();}}
    public async Task ReleaseJobAsync(CancellationToken ct=default){await _gate.WaitAsync(ct);try{if(_status==JobStatus.Running)throw new InvalidOperationException("Stop the active Job before leaving it.");_activeJobId=null;SetStatus(JobStatus.NewlyCreated);}finally{_gate.Release();}}
    private void OnSnapshot(object? s,PackingRuntimeSnapshot x){if(x.WorkflowState==PackingWorkflowState.Completed)SetStatus(JobStatus.Completed);}private void OnFailed(object? s,Exception ex){if(!_runtime.IsRunning)SetStatus(_runtime.Current?.WorkflowState==PackingWorkflowState.Completed?JobStatus.Completed:JobStatus.Paused);foreach(Action<Exception> h in RuntimeFailed?.GetInvocationList()??[])try{h(ex);}catch{}}private void SetStatus(JobStatus s){_status=s;foreach(Action<JobStatus> h in StatusChanged?.GetInvocationList()??[])try{h(s);}catch{}}
    public void Dispose(){if(_disposed)return;_disposed=true;_runtime.RuntimeFailed-=OnFailed;_runtime.SnapshotChanged-=OnSnapshot;_gate.Dispose();}
}
